class Solution {
public:
    vector<int> partitionLabels(string S) {
        unordered_map<int, int> last;                            // 哈希表，O(1)查找
        for (int i = 0; i < S.size(); i ++ ) last[S[i]] = i;
        vector<int> res;
        int start = 0, end = 0;
        for (int i = 0; i < S.size(); i ++ ) {
            end = max(end, last[S[i]]);
            if (i == end) {
                res.push_back(end - start + 1);                  // 记录结果
                start = end = i + 1;
            }
        }
        return res;
    }
};
